<div class="cms-content"><header class="cms-list-head"><div><h1>Photos &amp; files</h1><p>Upload and organise the images used across the website.</p></div></header><div class="cms-upload-layout"><section class="cms-card cms-upload-panel"><h2>Add a photo</h2><p>Use a clear filename and a short description. Images are ready to use after upload.</p><form method="post" enctype="multipart/form-data" action="<?= site_url('admin/media') ?>"><?= csrf_field() ?><label class="cms-field">Photo or image file<input type="file" name="file" accept="image/*" required></label><label class="cms-field">Description <small>For search and screen readers.</small><input name="alt_text" placeholder="e.g. Fresh fruit bunch harvest"></label><button class="cms-primary">Upload photo</button></form></section><section><div class="cms-media-filters"><span class="cms-filter active">All · <?= count($media) ?></span><span class="cms-filter">Needs description · <?= count(array_filter($media, static fn ($item) => empty($item['alt_text']))) ?></span></div><div class="cms-media-grid"><?php if (! $media): ?><p class="cms-empty">Photos you upload will appear here.</p><?php endif ?><?php foreach ($media as $item): ?><article class="cms-media-item"><img src="<?= base_url($item['path']) ?>" alt="<?= esc($item['alt_text']) ?>"><div class="cms-media-meta"><strong><?= esc($item['filename']) ?></strong><small><?= $item['alt_text'] ? esc($item['alt_text']) : 'Needs a description' ?></small><form method="post" action="<?= site_url('admin/media/' . $item['id'] . '/delete') ?>" onsubmit="return confirm('Delete this image?')"><?= csrf_field() ?><button>Delete</button></form></div></article><?php endforeach ?></div></section></div></div>
